# Create release directory and copy all files, excluding node_modules and .git
mkdir -p "$TEMP_DIR/release"
find . -mindepth 1 -maxdepth 1 ! -name 'node_modules' ! -name '.git' ! -name 'deploy.sh' ! -name '*.tar.gz' -exec cp -r {} "$TEMP_DIR/release/" \;

